using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Topology;

internal sealed class ColoredMatchingSwitchDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Circle counts under colored matching surgery.", H("Circle counts under colored matching surgery"), Blocks(
            Paragraph(Text("Let s, t and tPrime be fixed-point-free involutions of a finite type. Their two colors remain distinct even when both matchings join the same two darts. Circle(s,t) is the quotient by the equivalence relation generated by the two matching edges. Four pairwise distinct darts a,b,c,d satisfy t(a)=b, t(c)=d, tPrime(a)=c and tPrime(b)=d; the matchings agree at every other dart.")),
            Describe.Lean(DescribeId.Create("main-result"),
                DeclarationHandle.Create("D5/S3/Topology/ColoredMatchingSwitch.colored_switch_circle_count"),
                H("Circle counts under colored matching surgery"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("A two-edge replacement changes the number of circles by at most one. If a and c lie in different old circles, exactly two circles merge. Cutting the two old edges produces a first-return pairing on four endpoints. Circles avoiding those endpoints correspond bijectively before and after surgery. The affected circles correspond to the quotient of the first-return and reattachment pairings. Equal four-point pairings give two circles and distinct pairings give one, so the possible integer changes are minus one, zero and one. This argument retains parallel edges of different colors and does not require a planar embedding."))), DescribeRole.Theorem),
            Paragraph(Text("These finite matching statements are auxiliary to weaving coefficient asymptotics. They do not identify a state polynomial with the source trace-defined Jones invariant or establish the original twist-number limit.")))));
}
